use super::*;

const CORE_FILE: &str = "constants.ts";

#[test]
fn a_number_and_a_list_render_as_documented_constants() {
    let text = render(&[
        Constant::number("MAX_THINGS", "Most things.", 7_u16),
        Constant::numbers("STEPS", "The steps.", &[5_u16, 10]),
    ]);
    assert_eq!(
        text,
        "// This file was generated by focus-core. Do not edit this file manually.\n\
         \n\
         /** Most things. */\nexport const MAX_THINGS = 7;\n\
         \n\
         /** The steps. */\nexport const STEPS = [5, 10] as const;\n"
    );
}

#[test]
fn the_core_constants_follow_the_rust_values() {
    let text = render(&core_constants());
    assert!(text.contains("export const MAX_SITES = 500;"));
    assert!(text.contains("export const MAX_LIMIT_MINUTES = 1440;"));
    assert!(text.contains("export const COOLDOWN_STEPS_MINUTES = [5, 10, 20, 40] as const;"));
    assert!(text.contains("export const CONFIRM_WINDOW_MINUTES = 5;"));
    assert!(text.contains("export const MAX_DOMAIN_LEN = 249;"));
}

#[test]
fn the_host_alias_prefixes_are_exported_in_order() {
    let text = render(&core_constants());
    assert!(text.contains(
        "export const HOST_ALIAS_PREFIXES = [\"\", \"www.\", \"m.\", \"mobile.\", \"old.\", \"new.\", \"music.\", \"i.\", \"amp.\"] as const;"
    ));
}

#[test]
fn every_core_constant_has_a_unique_name() {
    let constants = core_constants();
    let mut names: Vec<&str> = constants.iter().map(|constant| constant.name).collect();
    names.sort_unstable();
    names.dedup();
    assert_eq!(names.len(), constants.len());
}

#[test]
fn the_core_constants_are_written_for_the_interface() {
    export(CORE_FILE, &core_constants()).unwrap();
}
